def build_result_final(grid, pat3):
    result = []
    for i_row in range(3):
        for r_block in range(3):
            new_row = []
            for i_col in range(3):
                val = grid[i_row][i_col]
                if val == 0:
                    row_pat = [0,0,0]
                elif val == 7:
                    row_pat = [7,0,7] if r_block != 1 else [0,0,0]
                elif val == 6:
                    row_pat = [6,6,0] if r_block == 0 else ([6,0,6] if r_block == 1 else [0,6,6])
                elif val == 4:
                    row_pat = [0,0,4] if r_block == 0 else ([4,4,0] if r_block == 1 else [4,4,0])
                elif val == 3:
                    row_pat = pat3[r_block]
                new_row.extend(row_pat)
            result.append(new_row)
    return result

test_in = [[0,0,3],[3,3,0],[0,3,0]]

pat_all = [[3,3,3],[3,3,3],[3,3,3]]
res_all = build_result_final(test_in, pat_all)

# Build the full 9x9 grid as proper nested list
grid_9x9 = [[res_all[r][c] % 10 for c in range(9)] for r in range(9)]

print("Final Grid (9x9):")
for r_idx, row in enumerate(grid_9x9):
    print(f"Row {r_idx}: {row}")

# Create JSON string
json_str = "[" + ",".join([str(v) for v in [val for row in grid_9x9 for val in row]]) + "]"
print(f"\nJSON Array: {json_str[:100]}...")
